def tags_to_categories(apps, schema_editor):
    """Turn the former free-text category ("tag") of each slot into a real category.

    Categories are created per event in the order in which their slots appear
    (slot position, then id); the slot positions are kept.
    """
    DutySlot = apps.get_model("pretix_parentduties", "DutySlot")
    DutyCategory = apps.get_model("pretix_parentduties", "DutyCategory")
    created = {}
    for slot in DutySlot.objects.exclude(tag="").order_by("event_id", "position", "id"):
        key = (slot.event_id, slot.tag.strip())
        if not key[1]:
            continue
        if key not in created:
            position = sum(1 for k in created if k[0] == slot.event_id)
            created[key] = DutyCategory.objects.create(event_id=slot.event_id, name=key[1], position=position)
        slot.category = created[key]
        slot.save(update_fields=["category"])


def categories_to_tags(apps, schema_editor):
    DutySlot = apps.get_model("pretix_parentduties", "DutySlot")
    for slot in DutySlot.objects.filter(category__isnull=False).select_related("category"):
        slot.tag = str(slot.category.name)[:190]
        slot.save(update_fields=["tag"])


